param([Parameter(Mandatory)][string]$BuildDirectory)
$ErrorActionPreference='Stop'
$prior=. "$PSScriptRoot\compare-runtime-remainders.ps1" -BuildDirectory $BuildDirectory
$priorReport=$prior|ConvertFrom-Json
$literalSymbols=@([regex]::Matches($map,'(?m)^\s*\S+\s+(\?\?_C@\S+|\?emptyErrorCaption@@3QBDB)\s+([0-9a-fA-F]{8})\b')|ForEach-Object {[pscustomobject]@{Symbol=$_.Groups[1].Value;VA=[Convert]::ToInt64($_.Groups[2].Value,16)}})
$expected=@(@(0x0100127c,'Delete'),@(0x01001284,'NoRemove'),@(0x01001290,'ForceRemove'),@(0x0100129c,'Val'),@(0x010012a0,'B'),@(0x010012a4,'D'),@(0x010012a8,'M'),@(0x010012ac,'S'),@(0x010012f8,'FS98MAIN'),@(0x01001304,'language.dll'),@(0x01001314,'D3DX9_34.DLL'),@(0x01001324,'D3DXCheckVersion'),@(0x01001338,'msxml4.manifest'),@(0x01001348,'API.DLL'),@(0x01001350,'GetApplication'),@(0x01001360,'Unable to install message filter'),@(0x01001384,"Error ID = %d`r`n%s"),@(0x010014c8,''))
$literalMap=@{};$strings=foreach($item in $expected){
 $va=[long]$item[0];$text=[string]$item[1];Require ((CString $a $va) -ceq $text) 'Original literal differs'
 $matches=@($literalSymbols|Where-Object {(CString $b $_.VA) -ceq $text});Require ($matches.Count -eq 1) "Expected one MAP-identified literal: $text"
 $new=$matches[0].VA;$literalMap[$va]=$new;$bytes=[Text.Encoding]::ASCII.GetBytes($text+[char]0)
 Equal-Bytes (Bytes $a $va $bytes.Length) (Bytes $b $new $bytes.Length) 'Literal with null terminator'
 [pscustomobject]@{Text=$text;OriginalVA=('{0:X8}' -f $va);RebuiltVA=('{0:X8}' -f $new);Bytes=$bytes.Length;RawExactMatch=$true;RebuiltSymbol=$matches[0].Symbol}
}
# Identify the observed eight-pointer token group by its complete mapped contents.
$targets=@(0x010012acL,0x010012a8L,0x010012a4L,0x010012a0L,0x0100129cL,0x01001290L,0x01001284L,0x0100127cL)
$pattern=[byte[]]::new(32);for($i=0;$i -lt 8;$i++){Require ((U32 $a (0x010012b0+4*$i)) -eq $targets[$i]) 'Original token-group pointer differs';[Array]::Copy([BitConverter]::GetBytes([uint32]$literalMap[$targets[$i]]),0,$pattern,4*$i,4)}
$hits=@(foreach($s in $b.Sections){for($offset=0;$offset+32 -le $s[1];$offset+=4){$rawOffset=$s[2]+$offset;if([BitConverter]::ToUInt32($b.Bytes,$rawOffset) -ne [BitConverter]::ToUInt32($pattern,0)){continue};$equal=$true;for($j=0;$j -lt 32;$j++){if($b.Bytes[$rawOffset+$j] -ne $pattern[$j]){$equal=$false;break}};if($equal){$b.Base+$s[0]+$offset}}})
Require ($hits.Count -eq 1) 'Expected unique eight-pointer token-group counterpart'
$tokenTable=$hits[0]
$load=Symbol '__load_config_used';$cookie=Symbol '___security_cookie';$seh=Symbol '___safe_se_handler_table'
$x=Bytes $a 0x010014d0 72;$y=Bytes $b $load 72
Require ((U32 $a 0x010014d0) -eq 72 -and (U32 $b $load) -eq 72 -and (Symbol '___safe_se_handler_count') -eq 2) 'Load config extent/handler count differs'
foreach($p in @(@(60,0x01004004,$cookie),@(64,0x01001560,$seh))){Require ([BitConverter]::ToUInt32($x,$p[0]) -eq $p[1] -and [BitConverter]::ToUInt32($y,$p[0]) -eq $p[2]) 'Load config pointer target differs';[Array]::Copy($x,$p[0],$y,$p[0],4)}
Equal-Bytes $x $y '72-byte load configuration'
foreach($p in @(@(0,0x01002768,'__except_handler4'),@(4,0x01002ca8,'__ehhandler$?InitializeOleAndMessageFilterPilot@@YAHXZ'))){Require ((U32 $a (0x01001560+$p[0])) -eq $p[1]-$a.Base -and (U32 $b ($seh+$p[0])) -eq (Symbol $p[2])-$b.Base) 'SafeSEH handler RVA differs'}
foreach($p in @(@($a,0x010014d0),@($b,$load))){$opt=[BitConverter]::ToInt32($p[0].Bytes,60)+24;Require ($p[0].Base+[BitConverter]::ToUInt32($p[0].Bytes,$opt+176) -eq $p[1] -and [BitConverter]::ToUInt32($p[0].Bytes,$opt+180) -eq 64) 'PE load-config directory association differs'}
$zeroSpans=foreach($r in @(@('Observed window storage',0x01004388,88,'?g_mainWindowPilot@@3VCWnd@@A'),@('Observed app storage including event',0x010043e0,168,'?g_fsxAppPilot@@3VFSXAppPilot@@A'),@('Application getter',0x01004384,4,'?pfnGetApplication@@3P6APAVApplicationPilot@@XZA'))){$new=Symbol $r[3];for($offset=0;$offset -lt $r[2];$offset+=4){Require ((Initial-Dword $a ($r[1]+$offset)) -eq 0 -and (Initial-Dword $b ($new+$offset)) -eq 0) 'Observed global zero storage differs'};[pscustomobject]@{Role=$r[0];OriginalVA=('{0:X8}' -f $r[1]);RebuiltVA=('{0:X8}' -f $new);Bytes=$r[2];InitialZeroMatch=$true}}
$states=foreach($p in @(@(0x01004018,'___globallocalestatus'),@(0x0100401c,'___defaultmatherr'),@(0x01004044,'__dowildcard'),@(0x01004048,'__newmode'),@(0x0100404c,'__commode'),@(0x01004050,'__fmode'),@(0x01004488,'__adjust_fdiv'),@(0x0100448c,'___native_startup_state'),@(0x01004490,'___native_startup_lock'),@(0x01004494,'___onexitend'),@(0x01004498,'___onexitbegin'),@(0x0100449c,'___dyn_tls_init_callback'))){$new=Symbol $p[1];$value=Initial-Dword $a $p[0];Require ($value -eq (Initial-Dword $b $new)) 'Named CRT initial state differs';[pscustomobject]@{Role=$p[1];OriginalVA=('{0:X8}' -f $p[0]);RebuiltVA=('{0:X8}' -f $new);InitialDword=('{0:X8}' -f $value)}}
$runtimeClasses=foreach($r in @(@('Application',0x01001398,'??_7FSXAppPilot@@6B@','?GetRuntimeClass@CWinApp@@UBEPAUCRuntimeClass@@XZ'),@('Filter',0x01001458,'??_7FSXMessageFilterPilot@@6B@','?GetRuntimeClass@CCmdTarget@@UBEPAUCRuntimeClass@@XZ'))){$table=Symbol $r[2];$target=Symbol $r[3];$identity=Thunk $a (U32 $a $r[1]);Require ((U32 $b $table) -eq $target -and $identity -ceq (Thunk $b $target)) 'MFC runtime-class dispatch identity differs';[pscustomobject]@{Role=$r[0];Import=$identity;RebuiltInheritedGetter=$r[3];IdentityVerified=$true}}
[pscustomobject]@{OriginalSHA256=$priorReport.OriginalSHA256;RebuiltSHA256=$priorReport.RebuiltSHA256;Strings=$strings;StringCount=$strings.Count;StringBytes=($strings|Measure-Object Bytes -Sum).Sum;TokenPointerGroup=@{OriginalVA='010012B0';RebuiltVA=('{0:X8}' -f $tokenTable);Entries=8;Bytes=32;TargetsVerified=$true};LoadConfiguration=@{OriginalVA='010014D0';RebuiltVA=('{0:X8}' -f $load);Bytes=72;TargetNormalizedExactMatch=$true;SafeSehTableBytes=8;SafeSehHandlerCount=2;SafeSehTargetsVerified=$true;PeDirectoryAssociationVerified=$true;PeDirectorySize=64;StructureSizeField=72};ZeroInitializedSpans=$zeroSpans;CrtInitialStates=$states;MfcRuntimeClassDispatch=$runtimeClasses;Scope='Stated literal bytes including null terminators, token-pointer group, load-config/SafeSEH fields, minimum observed global zero spans, named CRT initial dwords and inherited runtime-class dispatch only. Earlier runtime gates retained. No full class sizes, original private names, whole data coverage, file layout or runtime execution claim.'}|ConvertTo-Json -Depth 8
